DROP TABLE IF EXISTS "public"."customer";
-- Table Definition
CREATE TABLE "public"."customer" (
    "customer_id" uuid NOT NULL,
    "name_masked" text NOT NULL,
    "vpa_masked" text NOT NULL,
    "created_at" timestamptz NOT NULL DEFAULT now(),
    "anonymised_at" timestamptz,
    PRIMARY KEY ("customer_id")
);

DROP TABLE IF EXISTS "public"."transaction";
-- Table Definition
CREATE TABLE "public"."transaction" (
    "txn_id" text NOT NULL,
    "rail" text NOT NULL CHECK (rail = ANY (ARRAY['UPI'::text, 'IMPS'::text, 'NEFT'::text, 'RTGS'::text, 'MANDATE'::text])),
    "amount_inr" numeric(14,2) NOT NULL CHECK (amount_inr > (0)::numeric),
    "payer_id" uuid NOT NULL,
    "payee_id" uuid NOT NULL,
    "current_status" text NOT NULL,
    "created_at" timestamptz NOT NULL,
    PRIMARY KEY ("txn_id")
);

DROP TABLE IF EXISTS "public"."txn_event";
-- Table Definition
CREATE TABLE "public"."txn_event" (
    "event_id" uuid NOT NULL,
    "txn_id" text NOT NULL,
    "status" text NOT NULL,
    "response_code" text,
    "source_system" text NOT NULL,
    "event_time" timestamptz NOT NULL,
    PRIMARY KEY ("event_id")
);

DROP TABLE IF EXISTS "public"."knowledge_chunk";
-- Table Definition
CREATE TABLE "public"."knowledge_chunk" (
    "chunk_id" uuid NOT NULL,
    "document_name" text NOT NULL,
    "section" text,
    "page_number" int4,
    "published_date" date,
    "source_url" text,
    "text" text NOT NULL,
    "content_hash" text NOT NULL,
    "embedding" vector(384),
    PRIMARY KEY ("chunk_id")
);

DROP TABLE IF EXISTS "public"."approval_request";
-- Sequence and defined type
CREATE SEQUENCE IF NOT EXISTS approval_request_request_id_seq;

-- Table Definition
CREATE TABLE "public"."approval_request" (
    "request_id" int4 NOT NULL DEFAULT nextval('approval_request_request_id_seq'::regclass),
    "run_id" varchar(100),
    "action_type" varchar(50),
    "payload" jsonb,
    "status" varchar(20) DEFAULT 'PENDING'::character varying,
    "decided_by" varchar(50),
    "decision_reason" text,
    "decided_at" timestamp,
    PRIMARY KEY ("request_id")
);

DROP TABLE IF EXISTS "public"."fraud_flag";
-- Sequence and defined type
CREATE SEQUENCE IF NOT EXISTS fraud_flag_flag_id_seq;

-- Table Definition
CREATE TABLE "public"."fraud_flag" (
    "flag_id" int4 NOT NULL DEFAULT nextval('fraud_flag_flag_id_seq'::regclass),
    "txn_id" varchar(100) NOT NULL,
    "payee_id" varchar(100) NOT NULL,
    "fan_in_count" int4,
    "forwarding_ratio" numeric(5,2),
    "anomaly_score" float8,
    "llm_explanation" text,
    "analyst_feedback" varchar(20) DEFAULT 'PENDING'::character varying,
    "created_at" timestamp DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY ("flag_id")
);

DROP TABLE IF EXISTS "public"."audit_log";
-- Table Definition
CREATE TABLE "public"."audit_log" (
    "log_id" uuid NOT NULL DEFAULT gen_random_uuid(),
    "created_at" timestamptz DEFAULT now(),
    "user_role" text NOT NULL,
    "action_type" text NOT NULL,
    "txn_id" text,
    "details" jsonb,
    PRIMARY KEY ("log_id")
);


































